// generar_296_landing_links_rediseno.js
// CHIQUI Entre Señales — Landing /links rediseñada (versión con marca)
//
// Rediseño de la landing tipo linktree en /links siguiendo la
// referencia visual: tarjeta crema con forma de arco sobre fondo café,
// la ilustración oficial de las mascotas + logo CHIQUI como hero, y los
// accesos en tarjetas blancas con íconos.
//
// Cambios respecto a la versión anterior:
//   · HERO con la ilustración oficial (perros y gatos + logo CHIQUI),
//     en vez del Chiqui saludando.
//   · Android ahora enlaza al FORMULARIO de Google Forms para unirse a
//     la beta cerrada (más ordenado que el correo). Cuando exista el
//     link oficial de Google Play, se cambia GOOGLE_PLAY_URL y el botón
//     pasa solo a "Descargar en Google Play".
//   · iPhone con ícono de manzana 🍎 e instrucciones PWA desplegables.
//   · SE QUITA Samsung (su store exige cuenta de empresa).
//   · Redes (Instagram + correo) como botones circulares arriba.
//   · Footer "Hecho con AMOR para las mascotas y quienes las cuidan".
//
// Este script escribe DOS archivos:
//   1. app/links/page.tsx          (la página)
//   2. public/chiqui/chiqui_gatos_y_perros.png   (la ilustración)
//
// No hay SQL.
//
// Uso:
//   node generar_296_landing_links_rediseno.js

const fs2 = require('fs')
const path = require('path')

// Archivo de texto (la página)
const paginaTexto = {
  ruta: 'app/links/page.tsx',
  base64: ""
}

// Archivo binario (la imagen PNG)
const imagenBinaria = {
  ruta: 'public/chiqui/chiqui_gatos_y_perros.png',
  base64: ""
}

let errores = 0

// Escribir la página (texto UTF-8)
try {
  const rp = path.join(process.cwd(), paginaTexto.ruta)
  fs2.mkdirSync(path.dirname(rp), { recursive: true })
  fs2.writeFileSync(rp, Buffer.from(paginaTexto.base64, 'base64').toString('utf8'), 'utf8')
  console.log('OK: ' + paginaTexto.ruta)
} catch (e) {
  errores++
  console.error('ERROR escribiendo ' + paginaTexto.ruta + ': ' + e.message)
}

// Escribir la imagen (binario, SIN toString)
try {
  const ri = path.join(process.cwd(), imagenBinaria.ruta)
  fs2.mkdirSync(path.dirname(ri), { recursive: true })
  fs2.writeFileSync(ri, Buffer.from(imagenBinaria.base64, 'base64'))
  console.log('OK: ' + imagenBinaria.ruta)
} catch (e) {
  errores++
  console.error('ERROR escribiendo ' + imagenBinaria.ruta + ': ' + e.message)
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos (página + imagen).')
  console.log('git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
